package com.enterprise.procurement.service;

import com.enterprise.procurement.dto.ApplicationDtos; import com.enterprise.procurement.model.*; import com.enterprise.procurement.model.Enums.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.time.LocalDateTime; import java.time.format.DateTimeFormatter; import java.util.*; import java.util.concurrent.atomic.AtomicLong; import java.util.stream.Collectors;

@Service
public class ProcurementService {
    private final PasswordEncoder encoder; private final Map<Long,User> users=new LinkedHashMap<>(); private final Map<Long,Product> products=new LinkedHashMap<>(); private final Map<Long,Supplier> suppliers=new LinkedHashMap<>(); private final Map<Long,PurchaseApplication> applications=new LinkedHashMap<>(); private final Map<Long,PurchaseOrder> orders=new LinkedHashMap<>(); private final List<InventoryRecord> inventory=new ArrayList<>(); private final AtomicLong ids=new AtomicLong(10);
    public ProcurementService(PasswordEncoder encoder){this.encoder=encoder; seed();}
    private void seed(){users.put(1L,new User(1L,"admin",encoder.encode("admin123"),"系统管理员","管理部",Set.of(UserRole.ADMIN))); users.put(2L,new User(2L,"approver",encoder.encode("approver123"),"审批经理","财务部",Set.of(UserRole.APPROVER))); users.put(3L,new User(3L,"purchaser",encoder.encode("purchaser123"),"采购专员","采购部",Set.of(UserRole.PURCHASER))); products.put(1L,new Product(1L,"SKU-1001","办公笔记本电脑","办公设备","台",new BigDecimal("5999"),20)); products.put(2L,new Product(2L,"SKU-1002","人体工学办公椅","办公家具","把",new BigDecimal("899"),50)); suppliers.put(1L,new Supplier(1L,"SUP-001","华夏办公设备有限公司","张三","13800000001","上海市浦东新区")); suppliers.put(2L,new Supplier(2L,"SUP-002","优品供应链有限公司","李四","13800000002","深圳市南山区")); }
    public User findUser(String username){return users.values().stream().filter(u->u.getUsername().equals(username)&&u.isEnabled()).findFirst().orElse(null);} public boolean passwordMatches(User u,String p){return u!=null&&encoder.matches(p,u.getPassword());} public Collection<User> users(){return users.values();} public Collection<Product> products(){return products.values();} public Collection<Supplier> suppliers(){return suppliers.values();} public Collection<PurchaseApplication> applications(){return applications.values();} public Collection<PurchaseOrder> orders(){return orders.values();} public List<InventoryRecord> inventory(){return inventory;}
    public synchronized PurchaseApplication createApplication(String username,ApplicationDtos.CreateRequest req){User u=findUser(username); if(u==null)throw new IllegalArgumentException("用户不存在"); PurchaseApplication a=new PurchaseApplication(); a.setId(ids.incrementAndGet()); a.setApplicationNo("PA"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+a.getId()); a.setApplicantId(u.getId()); a.setApplicantName(u.getDisplayName()); a.setDepartment(u.getDepartment()); a.setReason(req.reason()); BigDecimal total=BigDecimal.ZERO; for(var i:req.items()){Product p=products.get(i.productId()); if(p==null)throw new IllegalArgumentException("商品不存在: "+i.productId()); var item=new PurchaseApplication.Item(p.getId(),p.getName(),i.quantity(),i.unitPrice()); a.getItems().add(item); total=total.add(item.amount());} a.setTotalAmount(total); a.setStatus(ApplicationStatus.PENDING); applications.put(a.getId(),a); return a;}
    public PurchaseApplication getApplication(Long id){return Optional.ofNullable(applications.get(id)).orElseThrow(()->new NoSuchElementException("采购申请不存在"));}
    public synchronized PurchaseApplication approve(Long id,String username,ApplicationDtos.ApprovalRequest req){PurchaseApplication a=getApplication(id); if(a.getStatus()!=ApplicationStatus.PENDING)throw new IllegalStateException("当前状态不可审批"); User u=findUser(username); if(u==null)throw new IllegalArgumentException("用户不存在"); a.getApprovals().add(new PurchaseApplication.ApprovalRecord(u.getId(),u.getDisplayName(),req.action(),req.comment())); a.setStatus(req.action()==ApprovalAction.APPROVE?ApplicationStatus.APPROVED:ApplicationStatus.REJECTED); a.setUpdatedAt(LocalDateTime.now()); return a;}
    public synchronized PurchaseOrder createOrder(Long appId,Long supplierId){PurchaseApplication a=getApplication(appId); if(a.getStatus()!=ApplicationStatus.APPROVED)throw new IllegalStateException("申请未审批通过"); Supplier s=suppliers.get(supplierId); if(s==null)throw new IllegalArgumentException("供应商不存在"); PurchaseOrder o=new PurchaseOrder(); o.setId(ids.incrementAndGet()); o.setOrderNo("PO"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+o.getId()); o.setApplicationId(appId); o.setSupplierId(supplierId); o.setSupplierName(s.getName()); o.setTotalAmount(a.getTotalAmount()); o.setItems(new ArrayList<>(a.getItems())); orders.put(o.getId(),o); a.setStatus(ApplicationStatus.PURCHASING); return o;}
    public synchronized PurchaseOrder receiveOrder(Long id){PurchaseOrder o=Optional.ofNullable(orders.get(id)).orElseThrow(()->new NoSuchElementException("采购订单不存在")); if(o.getStatus()==OrderStatus.COMPLETED)throw new IllegalStateException("订单已入库"); o.setStatus(OrderStatus.COMPLETED); for(var i:o.getItems()){Product p=products.get(i.getProductId()); if(p!=null)p.setStock(p.getStock()+i.getQuantity()); inventory.add(new InventoryRecord(ids.incrementAndGet(),p.getId(),p.getName(),i.getQuantity(),"IN",o.getOrderNo()));} PurchaseApplication a=applications.get(o.getApplicationId()); if(a!=null)a.setStatus(ApplicationStatus.COMPLETED); return o;}
}
